94	// Lazily resolves register handles. The plugin's vcpu_init runs before
95	// QEMU has registered the dynamic gdb coprocessors (FPU, virtual, csr,
96	// vector), so qemu_plugin_get_registers() returns only the 33 core CPU
97	// regs at that moment. By the time the entry trigger fires, all dynamic
98	// features are registered and a fresh call returns the full list.
99	static void resolve_handles(VcpuRegs *v)
100	{
101	    g_autoptr(GArray) regs = qemu_plugin_get_registers();
102	    for (int i = 0; i < 32; i++) {
103	        v->gpr[i] = find_reg(regs, hybrid_gpr_names[i]);
104	        v->fpr[i] = find_reg(regs, hybrid_fpr_names[i]);
105	    }
106	    v->pc = find_reg(regs, "pc");
107	
108	    v->mstatus  = find_reg(regs, "mstatus");
109	    v->mepc     = find_reg(regs, "mepc");
110	    v->mtvec    = find_reg(regs, "mtvec");
111	    v->mcause   = find_reg(regs, "mcause");
112	    v->mtval    = find_reg(regs, "mtval");
113	    v->mscratch = find_reg(regs, "mscratch");
114	    v->medeleg  = find_reg(regs, "medeleg");
115	    v->mideleg  = find_reg(regs, "mideleg");
116	    v->mip      = find_reg(regs, "mip");
117	    v->mie      = find_reg(regs, "mie");
118	    v->mcycle   = find_reg(regs, "mcycle");
119	    v->minstret = find_reg(regs, "minstret");
120	    v->satp     = find_reg(regs, "satp");
121	
122	    char buf[16];
123	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++) {
124	        g_snprintf(buf, sizeof(buf), "pmpcfg%d", i);
125	        v->pmpcfg[i] = find_reg(regs, buf);
126	    }
127	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++) {
128	        g_snprintf(buf, sizeof(buf), "pmpaddr%d", i);
129	        v->pmpaddr[i] = find_reg(regs, buf);
130	    }
131	
132	    v->vstart = find_reg(regs, "vstart");
133	    v->vxsat  = find_reg(regs, "vxsat");
134	    v->vxrm   = find_reg(regs, "vxrm");
135	    v->vcsr   = find_reg(regs, "vcsr");
136	    v->vtype  = find_reg(regs, "vtype");
137	    v->vl     = find_reg(regs, "vl");
138	    v->vlenb  = find_reg(regs, "vlenb");
139	    for (int i = 0; i < 32; i++) {
140	        g_snprintf(buf, sizeof(buf), "v%d", i);
141	        v->vreg[i] = find_reg(regs, buf);
