145	static uint64_t read_reg64(struct qemu_plugin_register *h)
146	{
147	    if (!h) return 0;
148	    g_autoptr(GByteArray) buf = g_byte_array_new();
149	    int sz = qemu_plugin_read_register(h, buf);
150	    if (sz <= 0) return 0;
151	    uint64_t v = 0;
152	    memcpy(&v, buf->data, sz < 8 ? (size_t) sz : 8);
153	    return v;
154	}
