199	// Drain CPU state to outfile_path. pc is computed by the caller (from a
200	// HandoffSite for trigger paths, or 0 for the atexit path which lacks an
201	// insn context). If minstret_override is non-zero, it replaces QEMU's PMU
202	// minstret in the state file (used by drain_at_exit mode to record a
203	// plugin-counted retired-insn total). Does NOT call exit -- caller
204	// decides exit(200) (normal trigger) vs _exit(200) (inside atexit chain).
205	static void drain_state_to_file(unsigned int vcpu_idx, uint64_t pc,
206	                                uint64_t minstret_override)
207	{
208	    VcpuRegs *v = qemu_plugin_scoreboard_find(vcpu_state, vcpu_idx);
209	    resolve_handles(v);
210	    struct hybrid_state_v1 s = {0};
211	    s.magic   = HYBRID_STATE_MAGIC;
212	    s.version = HYBRID_STATE_VERSION;
213	    s.flags   = HYBRID_FLAG_RV64;
214	    s.hart_id = vcpu_idx;
215	    s.priv    = 3;
216	    s.pc      = pc;
217	    for (int i = 0; i < 32; i++) s.gpr[i] = read_reg64(v->gpr[i]);
218	
219	    // Floating-point: only set FP flag if at least one handle was bound,
220	    // i.e. QEMU advertised the FPU feature (D extension).
221	    int has_fp = 0;
222	    for (int i = 0; i < 32; i++) {
223	        s.fpr[i] = read_reg64(v->fpr[i]);
224	        if (v->fpr[i]) has_fp = 1;
225	    }
226	    if (has_fp) s.flags |= HYBRID_FLAG_FP;
227	
228	    s.mstatus  = read_reg64(v->mstatus);
229	    s.mepc     = read_reg64(v->mepc);
230	    s.mtvec    = read_reg64(v->mtvec);
231	    s.mcause   = read_reg64(v->mcause);
232	    s.mtval    = read_reg64(v->mtval);
233	    s.mscratch = read_reg64(v->mscratch);
234	    s.medeleg  = read_reg64(v->medeleg);
235	    s.mideleg  = read_reg64(v->mideleg);
236	    s.mip      = read_reg64(v->mip);
237	    s.mie      = read_reg64(v->mie);
238	    s.mcycle   = read_reg64(v->mcycle);
239	    s.minstret = minstret_override ? minstret_override
240	                                   : read_reg64(v->minstret);
241	    s.satp     = read_reg64(v->satp);
242	
243	    for (int i = 0; i < HYBRID_PMP_CFG_NUM; i++)
244	        s.pmpcfg[i] = read_reg64(v->pmpcfg[i]);
245	    for (int i = 0; i < HYBRID_PMP_ADDR_NUM; i++)
246	        s.pmpaddr[i] = read_reg64(v->pmpaddr[i]);
247	
248	    // Vector: only set V flag if QEMU advertised the V extension. vlenb
249	    // bounds the per-register byte count copied into vreg[].
250	    s.vstart = read_reg64(v->vstart);
251	    s.vxsat  = read_reg64(v->vxsat);
252	    s.vxrm   = read_reg64(v->vxrm);
253	    s.vcsr   = read_reg64(v->vcsr);
254	    s.vtype  = read_reg64(v->vtype);
255	    s.vl     = read_reg64(v->vl);
256	    s.vlenb  = read_reg64(v->vlenb);
257	    if (v->vlenb && s.vlenb > 0) {
258	        s.flags |= HYBRID_FLAG_V;
259	        size_t bytes = s.vlenb < HYBRID_VLEN_BYTES_MAX
260	                     ? (size_t) s.vlenb
261	                     : (size_t) HYBRID_VLEN_BYTES_MAX;
262	        for (int i = 0; i < 32; i++)
263	            (void) read_reg_bytes(v->vreg[i],
264	                                  &s.vreg[(size_t) i * HYBRID_VLEN_BYTES_MAX],
265	                                  bytes);
266	    }
267	
268	    if (write_state_atomic(&s, outfile_path) != 0) {
269	        fprintf(stderr, "hybrid_handoff: failed to write state file\n");
270	        exit(2);
271	    }
272	    fprintf(stderr,
273	            "hybrid_handoff: drained state to %s (pc=%#" PRIx64 "), exiting\n",
274	            outfile_path, s.pc);
275	}
