277	static void on_handoff(unsigned int vcpu_idx, void *udata)
278	{
279	    const HandoffSite *site = (const HandoffSite *) udata;
280	    if (site->kind != HYBRID_HANDOFF_ENTER) return;
281	    // F14: suppress the atexit drain path now that we have a real trigger.
282	    drained_already = 1;
283	    // PC via translation-time vaddr+size; reading the gdbstub PC inside the
284	    // exec callback can lag the actual current insn when V instructions
285	    // retire just before the trigger (TCG defers PC writes for performance).
286	    drain_state_to_file(vcpu_idx, compute_handoff_pc(site), 0);
287	    // 200 == kExitHandoffToQemu in verilator/src/hybrid/exit_codes.hpp.
288	    // Distinguishes drain from workload completion (0) so the orchestrator
289	    // can decide the next spawn.
290	    exit(200);
291	}
292	
293	// F14: per-insn tick. Increments a global counter every retired insn so the
294	// drain-at-exit path can report a true retired-insn total (independent of
295	// QEMU's PMU semantics).
296	static void on_count_tick(unsigned int vcpu_idx, void *udata)
297	{
298	    (void) vcpu_idx;
299	    (void) udata;
300	    atexit_insn_count++;
301	}
302	
303	// F14: atexit drain. Fires when QEMU exits naturally (e.g. guest semihosting
304	// EXIT). The semihosting EXIT runs on the vCPU thread, so current_cpu is
305	// still set and qemu_plugin_read_register works. If any other trigger
306	// already drained, return immediately (drained_already guards against
307	// double drain). Inside an atexit handler, exit() is UB per C11 7.22.4.4;
308	// use _exit() to skip the rest of the atexit chain.
309	static void on_atexit(qemu_plugin_id_t id, void *udata)
310	{
311	    (void) id;
312	    (void) udata;
313	    if (drained_already) return;
314	    if (!drain_at_exit_mode) return;
315	    // pc=0 is a positive marker that the atexit path drained (no trigger).
316	    drain_state_to_file(0, 0, atexit_insn_count);
317	    fflush(stderr);
318	    _exit(200);
319	}
