321	static void vcpu_tb_trans(qemu_plugin_id_t id, struct qemu_plugin_tb *tb)
322	{
323	    (void) id;
324	    size_t n = qemu_plugin_tb_n_insns(tb);
325	
326	    for (size_t i = 0; i < n; i++) {
327	        struct qemu_plugin_insn *insn = qemu_plugin_tb_get_insn(tb, i);
328	
329	        // F14 count tick: registered FIRST so the count is incremented
330	        // before any trigger callback can call exit(200). NO_REGS keeps
331	        // the per-insn cost minimal (a single uint64 add).
332	        if (drain_at_exit_mode) {
333	            qemu_plugin_register_vcpu_insn_exec_cb(
334	                insn, on_count_tick, QEMU_PLUGIN_CB_NO_REGS, NULL);
335	        }
336	
337	        if (pc_mode) {
338	            // PC-trigger mode: vaddr-only match. qemu_plugin_insn_size lets
339	            // a future fixture park enter_pc on a compressed insn -- next-PC
340	            // is computed from the API-reported size, not assumed to be 4.
341	            if (qemu_plugin_insn_vaddr(insn) != enter_pc_arg) continue;
342	            HandoffSite *site = g_new0(HandoffSite, 1);
343	            site->kind  = HYBRID_HANDOFF_ENTER;
344	            site->vaddr = qemu_plugin_insn_vaddr(insn);
345	            site->size  = (uint32_t) qemu_plugin_insn_size(insn);
346	            qemu_plugin_register_vcpu_insn_exec_cb(
347	                insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
348	            continue;
349	        }
350	
351	        // CSR-trigger mode (default).
352	        size_t sz = qemu_plugin_insn_size(insn);
353	        if (sz != 4) continue;
354	        uint32_t raw = 0;
355	        if (qemu_plugin_insn_data(insn, &raw, sizeof(raw)) != sizeof(raw))
356	            continue;
357	        hybrid_handoff_kind kind = HYBRID_HANDOFF_NONE;
358	        if (!hybrid_match_handoff_insn(raw, &kind)) continue;
359	        HandoffSite *site = g_new0(HandoffSite, 1);
360	        site->kind  = kind;
361	        site->vaddr = qemu_plugin_insn_vaddr(insn);
362	        site->size  = (uint32_t) sz;
363	        qemu_plugin_register_vcpu_insn_exec_cb(
364	            insn, on_handoff, QEMU_PLUGIN_CB_R_REGS, site);
365	    }
366	}
